-- Stage 9: district texts (Gemini + editor). is_published stays false until owner approves production.
begin;
update public.districts set name_ru='Май Кхао и Най Янг', tagline='Тихий север Пхукета с национальным парком и длинными пляжами', intro='Mai Khao Beach — это длинный тихий пляж на самом севере Пхукета. Рядом находится Sirinat National Park — это прибрежный национальный парк на севере.', updated_at=now() where slug='mai-khao-nai-yang';
update public.districts set name_ru='Банг Тао', tagline='Длинные пляжи, торговые улицы и просторные курортные зоны', intro='Bang Tao Beach — это длинный песчаный пляж на западном побережье. Porto de Phuket — это открытый торговый комплекс в районе Чернгталай.', updated_at=now() where slug='bangtao';
update public.districts set name_ru='Камала и Сурин', tagline='Пляжи среди зелёных холмов и тематические парки', intro='Surin Beach — это песчаный пляж на западном побережье. Kamala Beach — это тихий и спокойный пляж на западном побережье среди зеленых холмов.', updated_at=now() where slug='kamala-surin';
update public.districts set name_ru='Патонг', tagline='Оживленный центр развлечений, магазинов и пляжного отдыха', intro='Patong Beach — это главный пляж Патонга с длинной песчаной бухтой и оживленным городом позади. Jungceylon — это большой торговый центр в сердце Патонга рядом с пляжем.', updated_at=now() where slug='patong';
update public.districts set name_ru='Карон и Ката', tagline='Широкие пляжи, семейные бухты и панорамные смотровые площадки', intro='Karon Beach — это длинный широкий песчаный пляж с расслабленной атмосферой. Kata Beach — это популярная семейная бухта с возможностью заняться серфингом.', updated_at=now() where slug='karon-kata';
update public.districts set name_ru='Раваи и Най Харн', tagline='Живописные южные бухты, озера и атмосферные мысы', intro='Nai Harn Beach — это пляж на юге Пхукета среди холмов. Promthep Cape — южная оконечность Пхукета со смотровой площадкой, маяком и святилищем.', updated_at=now() where slug='rawai-nai-harn';
update public.districts set name_ru='Чалонг', tagline='Культурные достопримечательности, храмы и спортивные лагеря', intro='Wat Chalong — один из главных буддийских храмовых комплексов острова. Phuket Big Buddha — это гигантская статуя Будды на холме Наккерд.', updated_at=now() where slug='chalong';
update public.districts set name_ru='Пхукет-Таун', tagline='Историческая архитектура, музеи и колоритные городские рынки', intro='Phuket Old Town — это исторический центр города с цветными домами. Chinpracha House — это исторический китайско-португальский особняк-музей.', updated_at=now() where slug='phuket-town';
commit;
